const mime = require("mime");
const fs = require("fs");

module.exports = (filePath, hexo) => {
    const log = hexo.log || console;
    const config = hexo.config.filter_base64;

    if (fs.existsSync(filePath)) {
        const type = mime.getType(filePath);
        if (type === null) {
            log.warn(`Unknown file type: ${filePath}`);
        } else {
            const data = fs.readFileSync(filePath);
            if (data.length < config.limit) return `data:${type};base64,${data.toString("base64")}`
        }
    } else {
        log.warn(`Image not found: ${filePath}`);
    }
};
